CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS instruments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider varchar(32) NOT NULL,market varchar(16) NOT NULL,symbol varchar(32) NOT NULL,base_asset varchar(16),quote_asset varchar(16),enabled boolean NOT NULL DEFAULT false,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT instrument_provider_symbol_uq UNIQUE(provider,symbol));
CREATE TABLE IF NOT EXISTS market_candles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),instrument_id uuid NOT NULL REFERENCES instruments(id),timeframe varchar(8) NOT NULL,open_time timestamptz NOT NULL,close_time timestamptz NOT NULL,open numeric(28,12) NOT NULL,high numeric(28,12) NOT NULL,low numeric(28,12) NOT NULL,close numeric(28,12) NOT NULL,volume numeric(36,12),is_complete boolean NOT NULL DEFAULT false,source varchar(32) NOT NULL,ingested_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT candle_instrument_tf_open_uq UNIQUE(instrument_id,timeframe,open_time));
CREATE INDEX IF NOT EXISTS candle_lookup_idx ON market_candles(instrument_id,timeframe,open_time DESC);
CREATE TABLE IF NOT EXISTS strategy_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key varchar(64) NOT NULL,version integer NOT NULL,name varchar(120) NOT NULL,description text,enabled boolean NOT NULL DEFAULT false,parameters jsonb NOT NULL,risk_config jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT strategy_key_version_uq UNIQUE(key,version));
CREATE TABLE IF NOT EXISTS signal_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dedupe_key varchar(180) NOT NULL UNIQUE,instrument_id uuid NOT NULL REFERENCES instruments(id),strategy_config_id uuid NOT NULL REFERENCES strategy_configs(id),market varchar(16) NOT NULL,symbol varchar(32) NOT NULL,direction varchar(8) NOT NULL,entry_type varchar(16) NOT NULL,entry_min numeric(28,12) NOT NULL,entry_max numeric(28,12) NOT NULL,stop_loss numeric(28,12) NOT NULL,targets jsonb NOT NULL,reward_risk numeric(12,4) NOT NULL,timeframe varchar(8) NOT NULL,rationale jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'published',published_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,invalidated_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS signal_symbol_published_idx ON signal_records(symbol,published_at DESC);
CREATE INDEX IF NOT EXISTS signal_status_expiry_idx ON signal_records(status,expires_at);
CREATE TABLE IF NOT EXISTS signal_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),signal_id uuid NOT NULL REFERENCES signal_records(id),event_type varchar(32) NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS backtest_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),strategy_key varchar(64) NOT NULL,strategy_version integer NOT NULL,instrument_id uuid REFERENCES instruments(id),timeframe varchar(8) NOT NULL,dataset jsonb NOT NULL,assumptions jsonb NOT NULL,metrics jsonb,status varchar(20) NOT NULL DEFAULT 'queued',started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notification_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),signal_id uuid NOT NULL REFERENCES signal_records(id),channel varchar(20) NOT NULL DEFAULT 'telegram',destination varchar(128) NOT NULL,status varchar(20) NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,provider_message_id varchar(128),last_error text,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT notification_signal_channel_destination_uq UNIQUE(signal_id,channel,destination));
CREATE INDEX IF NOT EXISTS notification_pending_idx ON notification_deliveries(status,next_attempt_at);
CREATE TABLE IF NOT EXISTS system_health (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),component varchar(64) NOT NULL UNIQUE,status varchar(16) NOT NULL,details jsonb NOT NULL DEFAULT '{}'::jsonb,checked_at timestamptz NOT NULL DEFAULT now());
